CustomField.formula:
IF(
    AND(
        OR(
            RecordType.DeveloperName = 'NSP_Credit_Specialist_Form',
            RecordType.DeveloperName = 'NSP_Client_Reinstatement'
        ),
        NOT(
            AND(
                CreatedBy.UserRole.DeveloperName = 'Payroll_Specialist',
                OR(
                    $Profile.Name = 'System Administrator',
                    $Profile.Name = 'System Admin Lite'
                )
            )
        )
    ),
    'Termination Team',
    IF(
        AND(
            CreatedBy.UserRole.DeveloperName = 'Finance_User',
            OR(
                $Profile.Name = 'System Administrator',
                $Profile.Name = 'System Admin Lite'
            )
        ),
        'Termination Team',
        IF(
            CreatedBy.UserRole.DeveloperName = 'Payroll_Specialist',
            NSP_Approver__r.FirstName & ' ' & NSP_Approver__r.MiddleName & ' ' & NSP_Approver__r.LastName,
            IF(
                AND(
                    CreatedBy.UserRole.DeveloperName = 'Credit_Specialist',
                    $UserRole.DeveloperName != 'System_Admin'
                ),
                NSP_Approver__r.FirstName & ' ' & NSP_Approver__r.MiddleName & ' ' & NSP_Approver__r.LastName,
                'Termination Team'
            )
        )
    )
)
